import{_ as a,o as i,c as t,a5 as r}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Plan","description":"","frontmatter":{},"headers":[],"relativePath":"feature/trend-s3-daily-replay/plan.md","filePath":"feature/trend-s3-daily-replay/plan.md"}'),o={name:"feature/trend-s3-daily-replay/plan.md"};function n(s,e,l,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="plan" tabindex="-1">Plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;Plan&quot;">​</a></h1><h2 id="neo4j-preflight-resilience-—-implementation-plan" tabindex="-1">Neo4j preflight resilience — implementation plan <a class="header-anchor" href="#neo4j-preflight-resilience-—-implementation-plan" aria-label="Permalink to &quot;Neo4j preflight resilience — implementation plan&quot;">​</a></h2><ol><li>AI: in app/services/replay_readiness.py separate a single read-only graph probe, transient-error classification and bounded async retry orchestration. Use monotonic deadlines and asyncio timeout/sleep; unwrap causes conservatively, failing closed for auth/TLS/configuration errors even if wrapped in ServiceUnavailable. Do not retry all Exceptions.</li><li>Retain the existing shared async driver from app/utils/neo4j.py. Retry the connectivity/APOC probe as a unit. Do not replace session.run everywhere or change the NLP/graph write path. Count configured driver activity within the outer attempt and total budgets.</li><li>app/services/replay_runner.py: verify wait_work cancellation and heartbeat remain effective while readiness retries/sleeps; preserve structured safe error codes and checkpoints. Change only what tests prove necessary; no automatic resume.</li><li>Web: map recognized job/day/file error codes to translations in TrendReplayDetail.tsx using existing alerts; preserve raw safe legacy codes as fallback. Add parallel messages to src/i18n/locales/vi/admin.json and en/admin.json for DNS/network timeout/auth/TLS/APOC and a safe recovery instruction. Do not expose server credentials in the UI.</li><li>Verification: ignored Python QA with fake drivers, simulated DNS/auth/TLS/timeouts and controllable sleep/clock; existing replay order/resume/lease tests. Browser mocks for error messages, explicit Resume, vi/en, keyboard, 375/768/1440 and light/dark; Web CI. Keep existing tracked tests as appropriate; no new tests under src and no local QA artifacts in commits.</li><li>Rollout: finish code/isolated checks before service changes. Ensure no active Replay before restarting AI (read-only Redis job/lease check); coordinate with the user if one is active. Avoid --reload during a long manual run. Deploy Web/AI together, then perform read-only Neo4j/APOC probes without invoking AI or modifying graph data.</li><li>Acceptance: transient first-attempt DNS failure followed by success allows readiness to proceed; persistent failures stop within budget, retain checkpoints, and show a useful category. Real archive Resume remains an explicit operator action and is not part of automatic validation.</li><li>Risk/rollback: retries can increase time before reporting a real outage, so show PREFLIGHT and retain status polling/heartbeat. Nested driver retry must not exceed the outer deadline. Revert only this scoped retry/message change if needed; no DB rollback or preview recreation is required. Keep other current uncommitted feature work intact.</li></ol><h2 id="s3-replay-source-separation-crawler-key-support" tabindex="-1">S3 replay source separation &amp; crawler key support <a class="header-anchor" href="#s3-replay-source-separation-crawler-key-support" aria-label="Permalink to &quot;S3 replay source separation &amp; crawler key support&quot;">​</a></h2><ol><li>Separate replay S3 configuration (<code>TREND_REPLAY_S3_BUCKET=crawler-social</code>, <code>TREND_REPLAY_S3_PREFIX=</code>) from media (<code>S3_BUCKET_NAME=brandhubmedia</code>). Expose <code>bucket</code> and <code>default_prefix</code> alongside <code>jobs</code> in the replay list endpoint; disallow client-chosen buckets.</li><li>Allow empty prefix to scan from bucket root when <code>TREND_REPLAY_S3_PREFIX</code> is empty (or constrain to <code>TREND_REPLAY_S3_PREFIX</code> when set). Parse both crawler <code>dd-MM-yyyy</code> and <code>YYYY-MM-DD</code>/<code>YYYYMMDD</code> key dates; exclude keys with missing or conflicting dates. Keep pinned job <code>bucket</code>, <code>prefix</code>, <code>key</code>, and <code>ETag</code> immutable across config changes.</li><li>Update Business DTO/service and Web replay form so prefix is optional, defaults from Backend config, displays the active S3 bucket, explains that an empty prefix scans the whole bucket, and retains the 31-day and 500-file limits and multi-platform 25-post batch pipeline.</li><li>Verify with mocked S3/Redis unit checks, browser QA, Web CI, and a read-only preview against <code>crawler-social</code> when AWS credentials are valid (without starting AI extraction).</li></ol><h2 id="multi-platform-update" tabindex="-1">Multi-platform update <a class="header-anchor" href="#multi-platform-update" aria-label="Permalink to &quot;Multi-platform update&quot;">​</a></h2><ol><li><p>Update replay_s3 discovery with conservative platform filename hints; add runtime platform counts to files.</p></li><li><p>Select registry adapter per raw platform/hint, normalize each adapter&#39;s timestamp fields while retaining original metadata. Use V3 contract and 25-row batches; prevent V2 resume without changing old checkpoints.</p></li><li><p>Update Web types/detail/form for platforms, translated stages and pipeline flow; validate dates before preview and retain API selection contract unchanged. Use shared Button and theme tokens for touched controls. Update vi/en admin.json.</p></li><li><p>Isolated adapter/runner/S3/Redis tests plus mocked browser QA and Web CI. No live S3 reads, paid extraction, replay starts or DB writes during verification.</p></li><li><p>Add bounded S3 manifest discovery/read module and request validation. Pin ETags, deterministic key dates and object sizes. Paginate listing; never arbitrary bucket.</p></li><li><p>Extend trend_run_store with optional root argument, preserving live defaults. Route replay through TrendService with separate history root and unchanged processing/persistence, then CrawlRunService finalization. Add historical daily snapshot support without changing normal live defaults.</p></li><li><p>Redis job store + leased async runner: start previewed job, sequential files/day, checkpoints, immutable source reads, safe failure and explicit resume.</p></li><li><p>AI internal /api/v1/ai/trends/replays preview/create/list/detail/resume routes.</p></li><li><p>Business Admin proxy controller/service + validated DTO, guarded authorization.</p></li><li><p>Feature-scoped Web service/types/hook/panels; Admin view/navigation and parallel src/i18n/locales/{vi,en}/admin.json keys; no new dependency/framework.</p></li><li><p>Isolated fake S3/Redis/pipeline checks and browser API-mocked fixture under keep-local-only; existing regressions, TypeScript/lint/build/Java compile.</p></li><li><p>Scoped old-trend preflight and cleanup only after user confirms stopped writers.</p></li><li><p>Read-only runtime preflight inside the leased async runner, before file work: Neo4j/APOC, Chroma heartbeat and MiniLM vector sanity. Import/model/network failures surface safe codes; no zero-vector or mock fallback. Restore missing dependencies from requirements, verify import compatibility, resume the existing job only when all checks pass. Do not reset checkpoints or replace the NLP model.</p></li></ol>',7)])])}const m=a(o,[["render",n]]);export{h as __pageData,m as default};
